const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function lineDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,n=dx*dx+dy*dy;if(!n)return distance(p,a);const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/n));return distance(p,{x:a.x+dx*t,y:a.y+dy*t});}
function simplify(points,epsilon){if(points.length<3)return points;let largest=0,index=0;for(let i=1;i<points.length-1;i++){const d=lineDistance(points[i],points[0],points.at(-1));if(d>largest){largest=d;index=i;}}return largest>epsilon?[...simplify(points.slice(0,index+1),epsilon).slice(0,-1),...simplify(points.slice(index),epsilon)]:[points[0],points.at(-1)];}
export function recognizeShape(raw){
 const points=raw.filter((p,i)=>!i||distance(p,raw[i-1])>.1);if(points.length<2)return null;
 const x0=Math.min(...points.map(p=>p.x)),x1=Math.max(...points.map(p=>p.x)),y0=Math.min(...points.map(p=>p.y)),y1=Math.max(...points.map(p=>p.y)),w=x1-x0,h=y1-y0,diag=Math.hypot(w,h);if(diag<5)return null;
 const first=points[0],last=points.at(-1),chord=distance(first,last),length=points.slice(1).reduce((n,p,i)=>n+distance(p,points[i]),0);
 if(chord>diag*.6&&length/chord<1.2&&points.every(p=>lineDistance(p,first,last)<Math.max(1,diag*.07)))return {kind:'line',name:'直线',points:[first,last],anchor:first};
 if(chord>Math.max(3,diag*.24))return null;
 let corners=simplify([...points,first],Math.max(1,diag*.045)).slice(0,-1);if(corners.length>2&&distance(corners[0],corners.at(-1))<diag*.12)corners.pop();
 if(corners.length===4){const edges=corners.map((p,i)=>({x:corners[(i+1)%4].x-p.x,y:corners[(i+1)%4].y-p.y}));const orthogonal=edges.every((a,i)=>{const b=edges[(i+1)%4];return Math.abs(a.x*b.x+a.y*b.y)/(Math.hypot(a.x,a.y)*Math.hypot(b.x,b.y))<.4;});if(orthogonal){const angle=Math.atan2(edges[0].y,edges[0].x),c=Math.cos(angle),s=Math.sin(angle),local=corners.map(p=>({x:(p.x-first.x)*c+(p.y-first.y)*s,y:-(p.x-first.x)*s+(p.y-first.y)*c})),a=Math.min(...local.map(p=>p.x)),b=Math.max(...local.map(p=>p.x)),d=Math.min(...local.map(p=>p.y)),e=Math.max(...local.map(p=>p.y));return {kind:'rectangle',name:'矩形',anchor:first,points:[[a,d],[b,d],[b,e],[a,e],[a,d]].map(([x,y])=>({x:first.x+x*c-y*s,y:first.y+x*s+y*c}))};}}
 if(w>2&&h>2){const cx=(x0+x1)/2,cy=(y0+y1)/2,error=points.reduce((n,p)=>n+Math.abs(Math.hypot((p.x-cx)/(w/2),(p.y-cy)/(h/2))-1),0)/points.length;if(error<.13&&corners.length>=5){const circle=Math.abs(w-h)/Math.max(w,h)<.16,rx=circle?(w+h)/4:w/2,ry=circle?rx:h/2,start=Math.atan2((first.y-cy)/ry,(first.x-cx)/rx),count=Math.max(32,Math.ceil(diag*3));return {kind:circle?'circle':'ellipse',name:circle?'圆形':'椭圆',anchor:first,points:Array.from({length:count+1},(_,i)=>{const t=start+i/count*Math.PI*2;return {x:cx+rx*Math.cos(t),y:cy+ry*Math.sin(t)};})};}}
 if(corners.length>=3&&corners.length<=8)return {kind:'polygon',name:corners.length+' 边形',anchor:first,points:[...corners,corners[0]]};return null;
}
export function adjustShape(shape,hold,current){const anchor=shape.anchor,reference=shape.points.reduce((a,p)=>distance(p,anchor)>distance(a,anchor)?p:a,anchor),vx=reference.x-anchor.x,vy=reference.y-anchor.y,dx=vx+current.x-hold.x,dy=vy+current.y-hold.y,base=Math.hypot(vx,vy)||1,scale=Math.max(.05,Math.min(20,Math.hypot(dx,dy)/base)),angle=Math.atan2(dy,dx)-Math.atan2(vy,vx),c=Math.cos(angle),s=Math.sin(angle);return shape.points.map(p=>{const x=p.x-anchor.x,y=p.y-anchor.y;return {x:Math.round(anchor.x+scale*(x*c-y*s)),y:Math.round(anchor.y+scale*(x*s+y*c))};});}
